 try{$pdo->exec("UPDATE enrollments e JOIN schedules sc ON sc.student_id=e.student_id AND sc.subject_id=e.subject_id JOIN subject_offerings o ON o.subject_id=sc.subject_id AND o.day_name=sc.day_name AND o.start_time=sc.start_time AND o.end_time=sc.end_time AND o.room=sc.room SET e.offering_id=o.id WHERE e.offering_id IS NULL");}catch(PDOException $e){}
} catch(PDOException $e){$error='Enrollment schedule setup could not be completed. Please contact Administration.';}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['request_enrollment']) && $isCurrent){
 $offeringId=(int)($_POST['offering_id']??0);$q=$pdo->prepare("SELECT o.*,s.code,s.name,s.units,s.prerequisite,u.name AS faculty_name FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id LEFT JOIN users u ON u.id=o.faculty_id WHERE o.id=?");$q->execute([$offeringId]);$offering=$q->fetch();
 if(!$offering)$error='The selected schedule is no longer available.';else{
  $dup=$pdo->prepare("SELECT e.id,e.status FROM enrollments e WHERE e.student_id=? AND e.subject_id=? AND e.term_id=? LIMIT 1");$dup->execute([$u['id'],$offering['subject_id'],$termId]);
  if($dup->fetch())$error='You already have an enrollment record for '.e($offering['code']).' in this academic term.';
  else{
   $conf=$pdo->prepare("SELECT sub.code,sub.name,sc.day_name,sc.start_time,sc.end_time FROM schedules sc JOIN subjects sub ON sub.id=sc.subject_id WHERE sc.student_id=? AND sc.term_id=? AND sc.day_name=? AND sc.start_time < ? AND sc.end_time > ?");$conf->execute([$u['id'],$termId,$offering['day_name'],$offering['end_time'],$offering['start_time']]);$conflicts=$conf->fetchAll();
   if($conflicts){$names=array_map(fn($c)=>$c['code'].' — '.$c['name'].' ('.date('g:i A',strtotime($c['start_time'])).'–'.date('g:i A',strtotime($c['end_time'])).')',$conflicts);$error='Not available. The selected schedule conflicts with your already enrolled subject(s): '.implode(', ',$names).'.';}
   else{$ins=$pdo->prepare("INSERT INTO enrollments(student_id,subject_id,offering_id,status,term_id) VALUES(?,?,?,'pending',?)");$ins->execute([$u['id'],$offering['subject_id'],$offeringId,$termId]);$eid=(int)$pdo->lastInsertId();$desc=$offering['code'].' — '.$offering['day_name'].' '.date('g:i A',strtotime($offering['start_time'])).'–'.date('g:i A',strtotime($offering['end_time'])).' with '.($offering['faculty_name']??'Assigned Faculty');log_transaction($pdo,(int)$u['id'],'Enrollment Request',$desc,'enrollment',$eid);notify_user($pdo,(int)$u['id'],'Enrollment request submitted','Your request for '.$desc.' is now pending.','Enrollment');$message='Enrollment request submitted for '.e($desc).'.';}
  }
 }
}
$mine=[];
if($isCurrent){$mineQ=$pdo->prepare("SELECT e.id AS enrollment_id,e.status,e.created_at,s.*,o.day_name,o.start_time,o.end_time,o.room,o.section AS offering_section,u.name AS faculty_name FROM enrollments e JOIN subjects s ON s.id=e.subject_id LEFT JOIN subject_offerings o ON o.id=e.offering_id LEFT JOIN users u ON u.id=o.faculty_id WHERE e.student_id=? AND e.term_id=? ORDER BY s.code");$mineQ->execute([$u['id'],$termId]);$mine=$mineQ->fetchAll();}
$subjectSearch=trim($_GET['q']??'');$available=[];$offerStmt=$pdo->prepare("SELECT o.*,u.name AS faculty_name,s.code,s.name,s.units FROM subject_offerings o LEFT JOIN users u ON u.id=o.faculty_id JOIN subjects s ON s.id=o.subject_id WHERE o.subject_id=? ORDER BY FIELD(o.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),o.start_time");
if($isCurrent){$availableSql="SELECT s.*,COUNT(o.id) offering_count FROM subjects s JOIN subject_offerings o ON o.subject_id=s.id WHERE s.id NOT IN(SELECT subject_id FROM enrollments WHERE student_id=".(int)$u['id']." AND term_id=".(int)$termId.")";$availableParams=[];if($subjectSearch!==''){$availableSql.=" AND (s.code LIKE ? OR s.name LIKE ?)";$like='%'.$subjectSearch.'%';$availableParams=[$like,$like];}$availableSql.=" GROUP BY s.id ORDER BY s.code";$av=$pdo->prepare($availableSql);$av->execute($availableParams);$available=$av->fetchAll();}
$current=[];$sq=$pdo->prepare("SELECT sc.*,sub.code,sub.name,sub.units FROM schedules sc JOIN subjects sub ON sub.id=sc.subject_id WHERE sc.student_id=? AND sc.term_id=?");$sq->execute([$u['id'],$termId]);$current=$sq->fetchAll();
$totalUnits=(int)array_sum(array_map(fn($r)=>(int)$r['units'],$mine));
require 'header.php';
