<script>
const currentSchedules=<?=json_encode($current,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
const summary=document.getElementById('enrollment-summary');
if(summary){const money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format((Number(n)||0));const mins=t=>{const p=t.split(':');return Number(p[0])*60+Number(p[1]);};const conflictFor=o=>currentSchedules.filter(s=>s.day_name===o.day&&mins(s.start_time)<mins(o.end)&&mins(s.end_time)>mins(o.start));document.querySelectorAll('.offering-select').forEach(card=>card.addEventListener('click',()=>{document.querySelectorAll('.offering-select').forEach(x=>x.classList.remove('selected'));card.classList.add('selected');const o={id:card.dataset.id,code:card.dataset.code,name:card.dataset.name,units:Number(card.dataset.units),day:card.dataset.day,start:card.dataset.start,end:card.dataset.end,room:card.dataset.room,section:card.dataset.section,teacher:card.dataset.teacher};summary.hidden=false;document.getElementById('selected-offering').value=o.id;document.getElementById('sum-subject').textContent=o.code+' — '+o.name;document.getElementById('sum-teacher').textContent=o.teacher;document.getElementById('sum-schedule').textContent=o.day+' · '+new Date('1970-01-01T'+o.start).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})+' – '+new Date('1970-01-01T'+o.end).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});document.getElementById('sum-room').textContent=o.section+' / '+o.room;document.getElementById('sum-units').textContent=o.units+' units';const approvedUnits=currentSchedules.reduce((sum,s)=>sum+Number(s.units||0),0);document.getElementById('sum-fees').textContent=money((approvedUnits+o.units)*<?=PROTOTYPE_TUITION_PER_UNIT?>+<?=PROTOTYPE_MISC_FEE?>);const conflicts=conflictFor(o),box=document.getElementById('conflict-box'),submit=document.getElementById('submit-request'),badge=document.getElementById('summary-status');if(conflicts.length){box.className='summary-check conflict';box.innerHTML='<b>Not available — schedule conflict.</b><p>This schedule overlaps with: '+conflicts.map(c=>c.code+' — '+c.name+' ('+c.day_name+' '+new Date('1970-01-01T'+c.start_time).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})+'–'+new Date('1970-01-01T'+c.end_time).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})+')').join(', ')+'.</p>';badge.textContent='Conflict';badge.className='badge conflict';submit.disabled=true;}else{box.className='summary-check clear';box.innerHTML='<b>No schedule conflicts detected.</b><p>This request can be submitted for Administration approval.</p>';badge.textContent='Available';badge.className='badge approved';submit.disabled=false;}summary.scrollIntoView({behavior:'smooth',block:'nearest'});}));}
</script>
